def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    fib_a, fib_b = 0, 1
    count = 0

    while True:
        # Check current Fibonacci number (fib_a)
        if is_prime(fib_a):
            count += 1
            if count == n:
                return fib_a

        # Generate next Fibonacci number
        fib_a, fib_b = fib_b, fib_a + fib_b

